arguments.content:
:root {
  --primary-dark: #1D1D1F;
  --light-bg: #F5F5F7;
  --white: #FFFFFF;
  --secondary-text: #6E6E73;
  --accent-blue: #0066CC;
  --border-color: #d2d2d7;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  color: var(--primary-dark);
  background-color: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: var(--accent-blue);
}

a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

/* Global Nav */
.global-nav {
  background-color: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
}

.global-nav .nav-content {
  max-width: 1000px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  padding: 15px 20px;
  font-size: 12px;
}

.global-nav a {
  color: var(--primary-dark);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity 0.2s;
}

.global-nav a:hover {
  opacity: 1;
}

/* Ribbon Banner */
.ribbon-banner {
  background-color: var(--light-bg);
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
}

/* Hero Section */
.hero {
  text-align: center;
  padding: 80px 20px;
  background-color: var(--light-bg);
}

.hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  margin-bottom: 10px;
}

.hero p {
  font-size: 24px;
  color: var(--primary-dark);
  margin-bottom: 20px;
}

.hero .cta-group {
  display: flex;
  justify-content: center;
  gap: 15px;
}

.btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 400;
  text-align: center;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--accent-blue);
  color: var(--white);
}

.btn-primary:hover {
  background-color: #005bb5;
  text-decoration: none;
}

.btn-secondary {
  background-color: transparent;
  color: var(--accent-blue);
  border: 1px solid var(--accent-blue);
}

.btn-secondary:hover {
  background-color: var(--accent-blue);
  color: var(--white);
  text-decoration: none;
}

.btn-buy {
  background-color: var(--accent-blue);
  color: var(--white);
  padding: 8px 16px;
  font-size: 12px;
}
.btn-buy:hover {
  background-color: #005bb5;
  text-decoration: none;
}

/* Grid Sections */
.grid-section {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 15px;
  padding: 15px;
  max-width: 1400px;
  margin: 0 auto;
}

@media (max-width: 768px) {
  .grid-section {
    grid-template-columns: 1fr;
  }
}

.grid-item {
  background-color: var(--light-bg);
  padding: 50px 20px;
  text-align: center;
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
}

.grid-item h2 {
  font-size: 40px;
  margin-bottom: 5px;
}

.grid-item p {
  font-size: 20px;
  margin-bottom: 15px;
}

/* Horizontal Carousels */
.carousel-section {
  padding: 60px 20px;
  max-width: 1400px;
  margin: 0 auto;
  position: relative;
}

.carousel-header {
  display: flex;
  align-items: baseline;
  margin-bottom: 30px;
}

.carousel-header h2 {
  font-size: 28px;
  font-weight: 600;
  margin-right: 15px;
}

.carousel-header span {
  font-size: 24px;
  color: var(--secondary-text);
}

.carousel-container {
  position: relative;
}

.carousel-track-wrapper {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none;  /* Internet Explorer 10+ */
}
.carousel-track-wrapper::-webkit-scrollbar { 
  display: none; /* WebKit */
}

.carousel-track {
  display: flex;
  gap: 20px;
  padding-bottom: 20px; /* shadow space */
}

.carousel-card {
  flex: 0 0 calc(33.333% - 20px);
  min-width: 300px;
  background: var(--white);
  border-radius: 18px;
  padding: 30px;
  scroll-snap-align: start;
  box-shadow: 0 4px 10px rgba(0,0,0,0.05);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s;
}

.carousel-card:hover {
  transform: scale(1.02);
}

.carousel-card.bg-light {
  background-color: var(--light-bg);
  box-shadow: none;
}

.carousel-card.bg-light:hover {
  transform: none;
}

.card-badge {
  font-size: 12px;
  color: #bf4800;
  font-weight: 500;
  margin-bottom: 10px;
  text-transform: uppercase;
}

.card-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 5px;
}

.card-desc {
  font-size: 14px;
  color: var(--secondary-text);
  margin-bottom: 20px;
}

.card-price {
  font-size: 14px;
  margin-bottom: 5px;
}

.card-monthly {
  font-size: 12px;
  color: var(--secondary-text);
  margin-bottom: 20px;
}

.card-image-placeholder {
  flex-grow: 1;
  background-color: var(--light-bg);
  border-radius: 12px;
  margin-bottom: 20px;
  min-height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--secondary-text);
  font-size: 12px;
}
.carousel-card.bg-light .card-image-placeholder {
  background-color: var(--white);
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  background: rgba(255,255,255,0.8);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 2px 5px rgba(0,0,0,0.2);
  z-index: 10;
  border: none;
  font-size: 20px;
}
.carousel-nav.prev {
  left: -20px;
}
.carousel-nav.next {
  right: -20px;
}

/* Category Navigation Bar */
.category-nav {
  position: sticky;
  top: 48px; /* below global nav */
  background: var(--white);
  border-bottom: 1px solid var(--border-color);
  z-index: 900;
}

.category-nav-list {
  display: flex;
  overflow-x: auto;
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 20px;
  scrollbar-width: none;
}
.category-nav-list::-webkit-scrollbar {
  display: none;
}

.category-nav-list li {
  white-space: nowrap;
}

.category-nav-list a {
  display: block;
  padding: 15px 20px;
  color: var(--primary-dark);
  font-size: 14px;
  opacity: 0.7;
}

.category-nav-list a:hover,
.category-nav-list a.active {
  opacity: 1;
  text-decoration: none;
}

/* Product Icon Bar */
.product-icon-bar {
  display: flex;
  justify-content: center;
  gap: 30px;
  padding: 40px 20px;
  overflow-x: auto;
  scrollbar-width: none;
}
.product-icon-bar::-webkit-scrollbar { display: none; }
.product-icon-item {
  text-align: center;
  font-size: 12px;
  cursor: pointer;
}
.product-icon-item .icon {
  width: 50px;
  height: 50px;
  background: var(--light-bg);
  border-radius: 50%;
  margin: 0 auto 10px;
}
.product-icon-item:hover { color: var(--accent-blue); }

/* Tabs / Entertainment */
.tabs-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 40px 20px;
}

.tabs-nav {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-bottom: 30px;
}

.tab-btn {
  background: none;
  border: none;
  font-size: 18px;
  cursor: pointer;
  padding: 10px 20px;
  color: var(--secondary-text);
  border-bottom: 2px solid transparent;
}

.tab-btn.active {
  color: var(--primary-dark);
  border-bottom-color: var(--primary-dark);
}

.tab-content {
  display: none;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.tab-content.active {
  display: grid;
}

@media (max-width: 768px) {
  .tab-content.active {
    grid-template-columns: 1fr;
  }
}

.entertainment-card {
  background: var(--light-bg);
  padding: 30px;
  border-radius: 18px;
  text-align: center;
}

/* Footer */
footer {
  background: var(--light-bg);
  padding: 40px 20px;
  font-size: 12px;
  color: var(--secondary-text);
  border-top: 1px solid var(--border-color);
}

.footer-content {
  max-width: 1000px;
  margin: 0 auto;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-bottom: 40px;
}

.footer-col h3 {
  color: var(--primary-dark);
  margin-bottom: 10px;
  font-weight: 600;
}

.footer-col ul li {
  margin-bottom: 8px;
}

.footer-col a {
  color: var(--secondary-text);
}

.footer-col a:hover {
  text-decoration: underline;
}

.footer-legal {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
}

/* Mobile Footer Accordion */
@media (max-width: 768px) {
  .footer-links {
    display: block;
  }
  .footer-col {
    border-bottom: 1px solid var(--border-color);
  }
  .footer-col h3 {
    padding: 15px 0;
    margin: 0;
    cursor: pointer;
    position: relative;
  }
  .footer-col h3::after {
    content: '+';
    position: absolute;
    right: 0;
    font-size: 16px;
  }
  .footer-col.active h3::after {
    content: '-';
  }
  .footer-col ul {
    display: none;
    padding-bottom: 15px;
  }
  .footer-col.active ul {
    display: block;
  }
  .footer-legal {
    flex-direction: column;
    gap: 10px;
  }
}

/* Utility */
.mb-1 { margin-bottom: 10px; }
.mb-2 { margin-bottom: 20px; }
.text-center { text-align: center; }
.section-pad { padding: 60px 20px; }
.max-w-1000 { max-width: 1000px; margin: 0 auto; }

document.addEventListener('DOMContentLoaded', () => {
  // Carousels
  const carousels = document.querySelectorAll('.carousel-container');
  carousels.forEach(container => {
    const track = container.querySelector('.carousel-track-wrapper');
    const prevBtn = container.querySelector('.carousel-nav.prev');
    const nextBtn = container.querySelector('.carousel-nav.next');

    if (track && prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        track.scrollBy({ left: -300, behavior: 'smooth' });
      });
      nextBtn.addEventListener('click', () => {
        track.scrollBy({ left: 300, behavior: 'smooth' });
      });
    }
  });

  // Entertainment Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active from all
      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));

      // Add active to clicked
      btn.classList.add('active');
      const targetId = btn.getAttribute('data-target');
      const targetContent = document.getElementById(targetId);
      if (targetContent) {
        targetContent.classList.add('active');
      }
    });
  });

  // Footer Accordion (Mobile)
  const footerCols = document.querySelectorAll('.footer-col h3');
  footerCols.forEach(colHeader => {
    colHeader.addEventListener('click', () => {
      if (window.innerWidth <= 768) {
        const parent = colHeader.parentElement;
        parent.classList.toggle('active');
      }
    });
  });

  // Sticky Category Nav Smooth Scroll
  const categoryLinks = document.querySelectorAll('.category-nav-list a[href^="#"]');
  categoryLinks.forEach(link => {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      const targetId = this.getAttribute('href');
      const targetElement = document.querySelector(targetId);
      if (targetElement) {
        const navHeight = document.querySelector('.category-nav').offsetHeight + document.querySelector('.global-nav').offsetHeight;
        const targetPosition = targetElement.getBoundingClientRect().top + window.pageYOffset - navHeight;

        window.scrollTo({
          top: targetPosition,
          behavior: 'smooth'
        });

        // Update active class
        categoryLinks.forEach(l => l.classList.remove('active'));
        this.classList.add('active');
      }
    });
  });
});
